import { type ColumnMap, type ColumnMapOptions, type ColumnSpec, defineColumnMap } from "@/registry/default/components/data-grid-server-query/data-grid-server-query";

/** A column spec of a Prisma model: `nullable` mirrors the schema's `?` on the field. */
export type PrismaColumnSpec = ColumnSpec & { nullable?: boolean };

type FieldOf<K, S> = S extends { field: infer F extends string } ? F : K;
type Nullability<M, F> = F extends keyof M ? (null extends M[F] ? { nullable: true } : { nullable?: false }) : unknown;

/**
 * Column specs whose `field` (or id, when `field` is absent) names a scalar field of the model, with `nullable: true`
 * exactly on the fields whose model type admits `null`.
 */
export type PrismaColumnSpecs<M, Field extends string, C> = {
  [K in keyof C]: PrismaColumnSpec & (K extends Field ? { field?: Field } : { field: Field }) & Nullability<M, FieldOf<K, C[K]>>;
};

const nullableIds = new WeakMap<ColumnMap, ReadonlySet<string>>();

/**
 * Validates a hand-written column map against a model, such as `User`, and its scalar fields, such as
 * `Prisma.UserScalarFieldEnum`: a column id or `field` the model lacks fails to compile and throws, and a column
 * whose `nullable` disagrees with the model type fails to compile. `required` only refuses blank writes.
 *
 * @example
 * const columns = definePrismaColumnMap<User>()(Prisma.UserScalarFieldEnum, {
 *   id: { type: "number", numeric: "int4", primaryKey: true },
 *   displayName: { type: "text", field: "name", searchable: true, nullable: true },
 * });
 */
export function definePrismaColumnMap<M extends object>() {
  return <const F extends Readonly<Record<string, string>>, const C extends Record<string, PrismaColumnSpec>>(
    fields: F,
    columns: C & PrismaColumnSpecs<M, F[keyof F], C>,
    options: ColumnMapOptions<keyof C & string> = {},
  ): ColumnMap<keyof C & string> => {
    const known = new Set<string>(Object.values(fields));
    for (const id of Object.keys(columns)) {
      const name = columns[id]!.field ?? id;
      if (!known.has(name)) throw new Error(`definePrismaColumnMap: column "${id}" names the field "${name}", which the model's scalar fields lack`);
    }
    const map = defineColumnMap(columns, options);
    nullableIds.set(map, new Set(Object.keys(columns).filter((id) => columns[id]!.nullable === true)));
    return map;
  };
}

/** The ids of the columns a map from {@link definePrismaColumnMap} marks `nullable`; any other map throws. */
export function nullableColumnIds(map: ColumnMap): ReadonlySet<string> {
  const ids = nullableIds.get(map);
  if (!ids) throw new Error("createPrismaGridQuery: `columns` must come from definePrismaColumnMap, which records the nullable fields");
  return ids;
}

import { type AdapterCapabilities, type ColumnMap, type GridQuery, QueryError, type QueryLimits, type RowCountMode, type RowScope } from "@/registry/default/components/data-grid-server-query/data-grid-server-query";
import { type AggregatesPlan, type GroupsPlan, type PlanColumn, type RawGroupRow, createGridQuery, mapOf, toSafeText } from "@/registry/default/components/data-grid-server-query/data-grid-server-query-sdk";
import {
  type PrismaNode,
  type PrismaOrderBy,
  type PrismaProvider,
  type PrismaWhere,
  and,
  assertBindBudget,
  boundValues,
  createPrismaRenderer,
  field,
  foldsEmptyText,
  isTextual,
  maxBoundIds,
  oneOf,
  or,
  own,
  toWhere,
  unsupported,
  writeValue,
} from "./render-prisma";
import { nullableColumnIds } from "./columns";

type Method = (...args: never[]) => unknown;

/** The model delegate of a generated Prisma client, such as `prisma.user`, typed by shape so the adapter imports no client. */
export type PrismaModelDelegate = { findMany: Method; count: Method; groupBy: Method; aggregate: Method };

export type PrismaGridQueryOptions<TContext = never> = {
  /** The model delegate of the table, such as `prisma.user`. */
  model: PrismaModelDelegate;
  /** The datasource `provider` of the schema. It sets the bound-value budget (PostgreSQL 32,766, SQLite 999), LIKE escaping, and `mode`. */
  provider: PrismaProvider;
  /** The map from `definePrismaColumnMap`, whose `nullable` mirrors the schema; another map throws. */
  columns: ColumnMap;
  /** Equalities on mapped columns that every query ANDs in. Needs `context` on every call. */
  rowScope?: RowScope<TContext>;
  /** When a rows request also counts the result. Default `"firstBlock"`. */
  rowCount?: RowCountMode;
  limits?: QueryLimits;
  /** IANA zone or fixed offset of day filters on `time` columns. Default `"UTC"`. */
  timeZone?: string;
  /** `"cursor"` pages `fetchRows` by keyset cursors and never counts; every sortable text column then needs `maxLength`, and a sortable native enum throws at creation. Default `"offset"`. */
  paging?: "offset" | "cursor";
  /** Most rows of the `groupBy` that counts a level's groups or a page's child groups; more is `limit-exceeded`. Default 10,000. */
  maxGroupRows?: number;
};

type Row = Record<string, unknown>;

const get = (row: unknown, key: string): unknown => (typeof row === "object" && row !== null && Object.hasOwn(row, key) ? (row as Row)[key] : null);
const isDecimal = (value: unknown): value is { toFixed(): string } =>
  typeof value === "object" && value !== null && !(value instanceof Date) && typeof (value as { toFixed?: unknown }).toFixed === "function";

/** Trailing zeros up to `scale`, as PostgreSQL returns `numeric(p, s)`; Prisma's `Decimal` drops them. */
function padToScale(text: string, scale: number | undefined): string {
  const dot = text.indexOf(".");
  const places = dot === -1 ? 0 : text.length - dot - 1;
  if (scale === undefined || places >= scale) return text;
  return `${text}${dot === -1 ? "." : ""}${"0".repeat(scale - places)}`;
}

/** A Prisma value in the form the core reads: `Decimal` and a `bigint` number as text, a date-only `Date` as its UTC day. */
function plainValue(column: PlanColumn, value: unknown): unknown {
  // The core reads an epoch `bigint` as an instant; its digits as text would read as no date.
  if (typeof value === "bigint") return column.kind === "date" ? value : value.toString();
  // decimal.js `toFixed()` with no argument never switches to exponent notation, unlike `toString()`.
  if (isDecimal(value)) return padToScale(value.toFixed(), column.scale);
  if (value instanceof Date && column.kind === "date" && !column.time) return Number.isNaN(value.getTime()) ? null : value.toISOString().slice(0, 10);
  return value;
}

const isBlankValue = (column: PlanColumn, value: unknown): boolean => value === null || value === undefined || (value === "" && foldsEmptyText(column));
const keyId = (column: PlanColumn, value: unknown): string => {
  if (isBlankValue(column, value)) return "blank";
  return `k:${value instanceof Date ? value.toISOString() : toSafeText(plainValue(column, value))}`;
};

/** `NULLIF(col, '')` in min, max, and count has no object-API form. */
function assertAggregates(columns: AggregatesPlan["columns"]): void {
  for (const { column, reducer } of columns) {
    if (reducer !== "sum" && reducer !== "avg" && isTextual(column) && !column.keepBlankText && column.native === undefined) throw unsupported(column);
  }
}

function aggregateSelection(columns: AggregatesPlan["columns"]): Record<string, Record<string, boolean>> {
  const out: Record<string, Record<string, boolean>> = {};
  for (const { column, reducer } of columns) own((out[`_${reducer}`] ??= {}), column.field, true);
  return out;
}

function aggregateValues(found: unknown, columns: AggregatesPlan["columns"]): Row {
  const out: Row = {};
  for (const { column, reducer } of columns) own(out, column.id, plainValue(column, get(get(found, `_${reducer}`), column.field)));
  return out;
}

/**
 * Reads and counts rows with a Prisma 7 model delegate, from the column map and a request body. It renders Prisma's object
 * API only and imports no client: pass `prisma.user` and the schema's `provider`.
 *
 * - Prisma has no runtime data model, so the map is written by hand with {@link definePrismaColumnMap}, typed by the
 *   generated model: `nullable` decides the NULL branches and `nulls: "last"`, which Prisma refuses on a field without `?`.
 * - Every statement counts its bound values and answers `limit-exceeded` past the provider budget (PostgreSQL 32,766,
 *   SQLite 999), because Prisma splits a plain `in` beyond it and merges wrong rows. On SQLite a selection of about 990
 *   ids or excluded ids, and a page of about 990 groups that have a next level, is `limit-exceeded`. `where` also reserves one value per mapped column for the `data` of a write.
 * - Its `capabilities` refuse, before any call, what the object API has no exact form for (`unsupported`): on SQLite
 *   case-insensitive `equals` and set filters, case-sensitive LIKE leaves, and excluded ids on a uuid key; on PostgreSQL
 *   cursor sorts on and grouping by `time` columns; LIKE leaves on a native enum or uuid; set values of `time` columns and
 *   of text without `caseSensitive`, and a value query on a non-text column; min, max, and count of text without
 *   `keepBlankText`. A custom operator throws at creation, and so does a sortable native enum with `paging: "cursor"`.
 * - On SQLite a `%` or `_` in a LIKE leaf is `unsupported-value`: SQLite LIKE has no ESCAPE clause there. On an `epoch-s`
 *   column a comparison or range rounds a fraction of a second to the exact whole second; any other instant with a
 *   fraction, such as an `equals` value or a written value, is `unsupported-value`.
 * - Group child counts and group counts read one extra `groupBy` of at most `maxGroupRows` rows.
 * - A pivot (`spec.pivot`) is `unsupported`: a two-field `groupBy` returns one row per group and key, 40,000 for a
 *   200-group page and 200 keys, past `maxGroupRows`, and it answers `''` and NULL as two keys.
 *
 * @example
 * import { Prisma, PrismaClient, type User } from "@/generated/prisma/client";
 *
 * const columns = definePrismaColumnMap<User>()(Prisma.UserScalarFieldEnum, {
 *   id: { type: "number", numeric: "int4", primaryKey: true },
 *   name: { type: "text", searchable: true, nullable: true },
 *   tenantId: { type: "number", numeric: "int4", serverOnly: true },
 * });
 * export const usersQuery = createPrismaGridQuery<User, Session>({ model: prisma.user, provider: "postgresql", columns, rowScope: (s) => ({ tenantId: s.tenantId }) });
 */
export function createPrismaGridQuery<TRow = Record<string, unknown>, TContext = never>(options: PrismaGridQueryOptions<TContext> & { paging: "cursor" }): GridQuery<TRow, TContext, PrismaWhere, PrismaOrderBy, string>;
export function createPrismaGridQuery<TRow = Record<string, unknown>, TContext = never>(options: PrismaGridQueryOptions<TContext> & { paging?: "offset" }): GridQuery<TRow, TContext, PrismaWhere, PrismaOrderBy>;
/** A `paging` known only at run time may page by cursor, so the answer's cursor is typed. */
export function createPrismaGridQuery<TRow = Record<string, unknown>, TContext = never>(options: PrismaGridQueryOptions<TContext>): GridQuery<TRow, TContext, PrismaWhere, PrismaOrderBy, string>;
export function createPrismaGridQuery<TRow, TContext>(options: PrismaGridQueryOptions<TContext>): GridQuery<TRow, TContext, PrismaWhere, PrismaOrderBy, string> {
  const { model, provider, columns } = options;
  if (provider !== "postgresql" && provider !== "sqlite") throw new Error('createPrismaGridQuery: `provider` must be "postgresql" or "sqlite"');
  for (const column of mapOf(columns).byId.values()) {
    if (column.operators.size > 0) throw new Error(`createPrismaGridQuery: column "${column.id}" declares a custom operator, which the Prisma adapter does not render`);
    if (options.paging === "cursor" && column.native === "enum" && column.sortable) {
      throw new Error(`createPrismaGridQuery: column "${column.id}" is a native enum, and a Prisma enum filter has no gt or lt to resume a cursor after it; set \`sortable: false\``);
    }
  }
  const maxGroupRows = options.maxGroupRows ?? 10_000;
  const renderer = createPrismaRenderer(provider, nullableColumnIds(columns));
  const pg = provider === "postgresql";

  const run = async (method: keyof PrismaModelDelegate, args: Row): Promise<unknown> => {
    for (const key of Object.keys(args)) boundValues(args[key]);
    assertBindBudget(args["where"], provider);
    return (model as unknown as Record<string, (input: Row) => PromiseLike<unknown>>)[method]!(args);
  };
  const many = async (method: "findMany" | "groupBy", args: Row): Promise<Row[]> => (await run(method, args)) as Row[];
  const where = (node: PrismaNode): PrismaWhere => toWhere(node);
  const select = (fields: readonly PlanColumn[]): Row => {
    const out: Row = {};
    for (const column of fields) own(out, column.field, true);
    return out;
  };
  const fromRow = (row: Row, projection: readonly PlanColumn[]): Row => {
    const out: Row = {};
    for (const column of projection) own(out, column.id, plainValue(column, get(row, column.field)));
    return out;
  };
  const tooMany = (rows: readonly unknown[]): void => {
    if (rows.length > maxGroupRows) throw new QueryError("limit-exceeded", ["spec", "groupBy"]);
  };

  const capabilities: AdapterCapabilities = {
    // SQLite: LIKE folds ASCII case and has no ESCAPE clause, `=` never folds, and `mode` is an unknown argument.
    caseInsensitiveText: pg ? "native" : "like-only",
    ...(pg ? {} : { caseSensitiveLike: false }),
    likeEscape: pg,
    literalAsterisk: true,
    nullsLast: pg ? "native" : "emulated",
    aggregates: true,
    groupBy: true,
    localDayGrouping: false,
    // Prisma reads a PostgreSQL DateTime in milliseconds, so a microsecond key would not compare back equal.
    exactInstantKeys: !pg,
    // Prisma's enum and `@db.Uuid` filters have no `contains`, `startsWith`, or `endsWith`.
    nativeLike: false,
    // `groupBy` takes fields only, and the object API has no `NULLIF(col, '')`.
    expressionValues: false,
    blankTextAggregates: false,
    // A two-field `groupBy` returns one row per group and key, past `maxGroupRows` at a full page.
    pivot: false,
    maxBoundIds: maxBoundIds(provider),
  };

  const pairWhere = (plan: GroupsPlan, keys: readonly unknown[], withBlank: boolean): PrismaWhere => {
    const { level } = plan;
    const blankLevel = withBlank ? renderer.blank(level, false, false, foldsEmptyText(level)) : false;
    return where(and([renderer.node(plan.where), or([keys.length > 0 ? oneOf(level, keys) : false, blankLevel])]));
  };
  const selectGroupPage = async (plan: GroupsPlan, page: { offset: number; limit: number }): Promise<RawGroupRow[]> => {
    assertAggregates(plan.aggregates);
    const { level } = plan;
    const base = renderer.node(plan.where);
    const emptyIsBlank = foldsEmptyText(level);
    const blankLevel = renderer.blank(level, false, false, emptyIsBlank);
    const keyed = where(and([base, renderer.blank(level, true, false, emptyIsBlank)]));
    const selection = aggregateSelection(plan.aggregates);
    own((selection["_count"] ??= {}), "_all", true);
    const order = [own({}, level.field, plan.direction)];
    const found = await many("groupBy", { by: [level.field], where: keyed, ...selection, orderBy: order, skip: page.offset, take: page.limit });
    const groupRow = (group: unknown, key: unknown): RawGroupRow => ({
      key: plainValue(level, key),
      count: get(get(group, "_count"), "_all"),
      childCount: null,
      aggregates: aggregateValues(group, plan.aggregates),
    });
    const keys = found.map((group) => get(group, level.field));
    const rows = found.map((group, index) => groupRow(group, keys[index]));
    // The blank group sorts last in both directions: it is on this page when the non-blank groups end inside it.
    const endsHere = async () => found.length > 0 || page.offset === 0 || (await many("groupBy", { by: [level.field], where: keyed, orderBy: order, skip: page.offset - 1, take: 1 })).length > 0;
    let blankOnPage = false;
    if (blankLevel !== false && found.length < page.limit && (await endsHere())) {
      const blank = await run("aggregate", { where: where(and([base, blankLevel])), ...selection });
      blankOnPage = Number(get(get(blank, "_count"), "_all")) > 0;
      if (blankOnPage) rows.push(groupRow(blank, null));
    }
    const next = plan.nextLevel;
    if (!next || rows.length === 0) return rows;
    // `_count` is COUNT(col), not a distinct count, so the child groups come from a second groupBy over this page's keys.
    const pairs = await many("groupBy", {
      by: [level.field, next.field],
      where: pairWhere(plan, keys, blankOnPage),
      orderBy: [own({}, level.field, "asc"), own({}, next.field, "asc")],
      take: maxGroupRows + 1,
    });
    tooMany(pairs);
    // A set per level key: the `''` and NULL rows of either level fold into one group.
    const children = new Map<string, Set<string>>();
    for (const pair of pairs) {
      const id = keyId(level, get(pair, level.field));
      const set = children.get(id) ?? new Set<string>();
      set.add(keyId(next, get(pair, next.field)));
      children.set(id, set);
    }
    const groupKeys = [...keys, ...(blankOnPage ? [null] : [])];
    return rows.map((row, index) => ({ ...row, childCount: children.get(keyId(level, groupKeys[index]))?.size ?? 0 }));
  };

  return createGridQuery<TRow, TContext, PrismaWhere, PrismaOrderBy, string>({
    columns,
    rowScope: options.rowScope,
    rowCount: options.rowCount,
    limits: options.limits,
    timeZone: options.timeZone,
    paging: options.paging,
    executor: {
      capabilities,
      where: (plan) => {
        const rendered = where(renderer.node(plan.where));
        // A write's `data` binds one value per written field, at most one per mapped column, next to the take and skip reserve.
        assertBindBudget(rendered, provider, 2 + mapOf(columns).byId.size);
        return rendered;
      },
      orderBy: (plan) => renderer.orderBy(plan.orderBy),
      nativeValue: writeValue,
      selectRows: async (plan, page) => {
        const keyText = plan.keyText ?? [];
        const fields = select([...plan.projection, ...keyText.map(({ column }) => column)]);
        const rows = await many("findMany", { where: where(renderer.node(plan.where)), orderBy: renderer.orderBy(plan.orderBy), skip: page.offset, take: page.limit, select: fields });
        return rows.map((row) => {
          const out = fromRow(row, plan.projection);
          // Only SQLite asks for `keyText`: the stored text or integer is the exact key, a `DateTime` a millisecond `Date`.
          for (const { column, as } of keyText) {
            const raw = get(row, column.field);
            own(out, as, raw instanceof Date ? raw.toISOString() : raw);
          }
          return out;
        });
      },
      countRows: async (plan) => run("count", { where: where(renderer.node(plan.where)) }),
      selectValues: async (plan, { limit }) => {
        const { column } = plan;
        if (column.time || (isTextual(column) && !column.caseSensitive) || (!isTextual(column) && plan.query !== "")) throw unsupported(column);
        const base = renderer.node(plan.where);
        const matched = plan.query === "" ? base : and([base, field(column, renderer.textFilter(column, "contains", plan.query, false))]);
        const emptyIsBlank = foldsEmptyText(column);
        const groups = await many("groupBy", {
          by: [column.field],
          where: where(and([matched, renderer.blank(column, true, false, emptyIsBlank)])),
          _count: own({}, column.field, true),
          orderBy: [{ _count: own({}, column.field, "desc") }, own({}, column.field, "asc")],
          take: limit,
        });
        const found = groups.map((group) => ({ value: plainValue(column, get(group, column.field)), count: get(get(group, "_count"), column.field) }));
        const blank = renderer.blank(column, false, false, emptyIsBlank);
        // A value query never matches a blank value.
        if (plan.query === "" && blank !== false) {
          const count = await run("count", { where: where(and([base, blank])) });
          if (Number(count) > 0) found.push({ value: null, count });
        }
        return found;
      },
      aggregate: async (plan) => {
        assertAggregates(plan.columns);
        return aggregateValues(await run("aggregate", { where: where(renderer.node(plan.where)), ...aggregateSelection(plan.columns) }), plan.columns);
      },
      selectGroups: selectGroupPage,
      countGroups: async (plan) => {
        const { level } = plan;
        const groups = await many("groupBy", { by: [level.field], where: where(renderer.node(plan.where)), orderBy: [own({}, level.field, "asc")], take: maxGroupRows + 1 });
        tooMany(groups);
        // NULL and `''` are one group, as the SQL renderers' NULLIF folds them.
        const blank = groups.some((group) => isBlankValue(level, get(group, level.field)));
        return groups.filter((group) => !isBlankValue(level, get(group, level.field))).length + (blank ? 1 : 0);
      },
    },
  });
}

import { QueryError } from "@/registry/default/components/data-grid-server-query/data-grid-server-query";
import { type Operand, type OrderTerm, type PlanColumn, type Predicate, type Test, escapeLike } from "@/registry/default/components/data-grid-server-query/data-grid-server-query-sdk";

/** A Prisma `where` input of the model. */
export type PrismaWhere = Record<string, unknown>;
/** A Prisma `orderBy` input of the model. */
export type PrismaOrderBy = Record<string, unknown>[];
/** The `provider` of the Prisma schema's datasource. */
export type PrismaProvider = "postgresql" | "sqlite";

/** A rendered predicate: `true` and `false` stay constants until the root, so no `{}` lands inside an `OR`. */
export type PrismaNode = boolean | PrismaWhere;

// Prisma 7.10.1 bounds the bound values of one statement by the driver adapter's `maxBindValues`, else by these provider defaults; adapter-pg and adapter-better-sqlite3 7.10.1 set none.
const BIND_BUDGET: Readonly<Record<PrismaProvider, number>> = { postgresql: 32_766, sqlite: 999 };
// The LIMIT and OFFSET (or Prisma's own extra values) of a statement.
const RESERVED_BINDS = 2;
const LIKE_MODES = new Set<string>(["contains", "startsWith", "endsWith"]);

/** Sets an own data property, so a key such as `__proto__` stays a plain key. */
export function own<T extends object>(target: T, key: string, value: unknown): T {
  Object.defineProperty(target, key, { value, enumerable: true, writable: true, configurable: true });
  return target;
}

export const field = (column: PlanColumn, filter: unknown): PrismaWhere => own({}, column.field, filter);
export const isTextual = (column: PlanColumn): boolean => column.kind === "text" || column.kind === "select";
/** Whether a stored `''` counts as blank in a group key or a set value, as the SQL renderers fold it into NULL. */
export const foldsEmptyText = (column: PlanColumn): boolean => isTextual(column) && column.native === undefined;
export const unsupported = (column: PlanColumn): QueryError => new QueryError("unsupported", [column.id]);

// A Prisma Boolean filter has no `in` or `notIn`.
const hasNoList = (column: PlanColumn): boolean => column.kind === "checkbox";

/** The rows whose field is one of `values`: `in`, or an OR of `equals` on a Boolean field. */
export function oneOf(column: PlanColumn, values: readonly unknown[], leaf: (filter: Record<string, unknown>) => PrismaNode = (filter) => field(column, filter)): PrismaNode {
  return hasNoList(column) ? or(values.map((v) => leaf({ equals: v }))) : leaf({ in: values });
}

/** Folds the constants and flattens nested groups of the same join; no group comes out empty. */
function join(key: "AND" | "OR", items: readonly PrismaNode[]): PrismaNode {
  const neutral = key === "AND";
  const out: PrismaWhere[] = [];
  for (const item of items) {
    if (typeof item === "boolean") {
      if (item !== neutral) return item;
      continue;
    }
    const keys = Object.keys(item);
    if (keys.length === 1 && keys[0] === key && Array.isArray(item[key])) out.push(...(item[key] as PrismaWhere[]));
    else out.push(item);
  }
  return out.length === 0 ? neutral : out.length === 1 ? out[0]! : own({}, key, out);
}

export const and = (items: readonly PrismaNode[]): PrismaNode => join("AND", items);
export const or = (items: readonly PrismaNode[]): PrismaNode => join("OR", items);

const not = (item: PrismaNode): PrismaNode => (typeof item === "boolean" ? !item : { NOT: item });

export const toWhere = (node: PrismaNode): PrismaWhere => (node === true ? {} : node === false ? { OR: [] } : node);

const isPlainObject = (value: object): boolean => {
  const prototype: unknown = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
};

/** The bound values of an input; throws on `undefined`, which Prisma drops silently, and on `{}` inside `OR`, which matches nothing. */
export function boundValues(node: unknown, inOr = false): number {
  if (node === undefined) throw new Error("gridcn Prisma adapter: an undefined value would drop a filter");
  if (node === null) return 0;
  if (typeof node !== "object" || !(Array.isArray(node) || isPlainObject(node))) return 1;
  if (Array.isArray(node)) return node.reduce((sum: number, item: unknown) => sum + boundValues(item, inOr), 0);
  const keys = Object.keys(node);
  if (inOr && keys.length === 0) throw new Error("gridcn Prisma adapter: an empty filter inside OR would match nothing");
  let count = 0;
  for (const key of keys) {
    const value = (node as Record<string, unknown>)[key];
    if (key === "mode" && typeof value === "string") continue;
    count += boundValues(value, key === "OR");
  }
  return count;
}

/** The longest id list a statement of `provider` binds next to the take and skip reserve. */
export const maxBoundIds = (provider: PrismaProvider): number => BIND_BUDGET[provider] - RESERVED_BINDS;

/** Refuses a statement whose `where` binds more values than the provider takes: Prisma splits a plain `in` beyond it and merges wrong results. */
export function assertBindBudget(where: unknown, provider: PrismaProvider, reserved = RESERVED_BINDS): void {
  if (boundValues(where) + reserved > BIND_BUDGET[provider]) throw new QueryError("limit-exceeded", []);
}

/** The operand as the Prisma field type takes it: `BigInt` for int8, text for decimals, `Date` for native dates. */
export function nativeValue(column: PlanColumn, operand: Operand): unknown {
  switch (operand.kind) {
    case "text":
    case "boolean":
      return operand.v;
    case "bigint":
      return column.numeric === "int8" ? operand.v : column.numeric === "decimal" ? operand.v.toString() : Number(operand.v);
    case "number":
      return column.numeric === "decimal" ? operand.v : Number(operand.v);
    case "date":
      return column.storage === "native" ? new Date(`${operand.v}T00:00:00.000Z`) : operand.v;
    case "instant":
      if (column.storage === "epoch-ms") return Date.parse(operand.v);
      if (column.storage === "epoch-s") {
        const ms = Date.parse(operand.v);
        // Prisma truncates a fraction bound to an Int field, so `gte 1.5` would match 1.
        if (ms % 1000 !== 0) throw new QueryError("unsupported-value", [column.id]);
        return ms / 1000;
      }
      return column.storage === "iso-text" ? operand.v : new Date(operand.v);
  }
}

/** A validated write value as the Prisma field type takes it: integers as numbers or `BigInt`, dates as `Date`. */
export function writeValue(column: PlanColumn, value: unknown): unknown {
  if (value === null) return null;
  if (column.kind === "number" && column.numeric !== "float" && column.numeric !== "decimal") return nativeValue(column, { kind: "bigint", v: BigInt(value as number | string) });
  if (column.kind === "date" && typeof value === "string") return nativeValue(column, { kind: column.time ? "instant" : "date", v: value });
  return value;
}

/** `nullableIds`: the columns whose field the schema declares with `?`; Prisma refuses `null` filters and `nulls` on the others. */
export function createPrismaRenderer(provider: PrismaProvider, nullableIds: ReadonlySet<string>) {
  const pg = provider === "postgresql";
  const isNullable = (column: PlanColumn): boolean => nullableIds.has(column.id);
  const escape = (text: string): string => escapeLike(text, "\\");
  const value = (column: PlanColumn, operand: Operand): unknown => nativeValue(column, operand);
  const isNull = (column: PlanColumn): PrismaNode => (isNullable(column) ? field(column, null) : false);
  /** A comparison bound; on an `epoch-s` column `gt` and `lte` floor a fraction of a second, `gte` and `lt` ceil it. */
  const bound = (column: PlanColumn, op: "gt" | "gte" | "lt" | "lte", operand: Operand): unknown =>
    column.storage === "epoch-s" && operand.kind === "instant" ? (op === "gt" || op === "lte" ? Math.floor : Math.ceil)(Date.parse(operand.v) / 1000) : value(column, operand);

  /** The leaf, false on NULL rows when `twoValued`: under `NOT`, Prisma's three-valued logic drops the NULL rows otherwise. */
  function fieldLeaf(column: PlanColumn, filter: Record<string, unknown>, twoValued: boolean): PrismaWhere {
    if (!twoValued || !isNullable(column)) return field(column, filter);
    return "not" in filter ? { AND: [field(column, filter), field(column, { not: null })] } : field(column, { ...filter, not: null });
  }

  /** The field filter of a text test. On PostgreSQL every LIKE leaf and an insensitive `equals` (ILIKE) escape `%`, `_`, and `\`. */
  function textFilter(column: PlanColumn, mode: "contains" | "startsWith" | "endsWith" | "equals", text: string, caseSensitive: boolean): Record<string, unknown> {
    const like = LIKE_MODES.has(mode);
    // The core refuses these from the capabilities; the throws keep a missed path from matching wrong rows.
    if (like && column.native !== undefined) throw unsupported(column);
    if (!pg) {
      // SQLite: LIKE is ASCII case-insensitive with no ESCAPE clause, `=` is case-sensitive, and `mode` is an unknown argument.
      if (like === caseSensitive) throw unsupported(column);
      if (like && /[%_]/.test(text)) throw new QueryError("unsupported-value", [column.id]);
      return own({}, mode, text);
    }
    if (mode === "equals" && caseSensitive) return { equals: text };
    return caseSensitive ? own({}, mode, escape(text)) : own({ mode: "insensitive" }, mode, escape(text));
  }

  /** NULL, and on text that folds it `''`; `negate` is the rows with a non-blank value. */
  function blank(column: PlanColumn, negate: boolean, twoValued: boolean, emptyIsBlank = isTextual(column) && !column.keepBlankText && column.native === undefined): PrismaNode {
    if (!emptyIsBlank) return negate ? (isNullable(column) ? field(column, { not: null }) : true) : isNull(column);
    return negate ? fieldLeaf(column, { not: "" }, twoValued) : or([isNull(column), field(column, { equals: "" })]);
  }

  const guarded = (column: PlanColumn, filter: Record<string, unknown>): Record<string, unknown> =>
    isTextual(column) && !column.keepBlankText && column.native === undefined ? { ...filter, not: "" } : filter;

  function inList(column: PlanColumn, t: Extract<Test, { k: "in" }>, twoValued: boolean): PrismaNode {
    const values = t.values.map((operand) => value(column, operand));
    const folded = !t.caseSensitive && isTextual(column);
    if (folded && !pg) throw unsupported(column);
    const member = (two: boolean): PrismaNode =>
      folded ? or(values.map((text) => fieldLeaf(column, { equals: escape(String(text)), mode: "insensitive" }, two))) : oneOf(column, values, (filter) => fieldLeaf(column, filter, two));
    if (!t.negate) return t.blank ? or([member(twoValued), blank(column, false, twoValued)]) : member(twoValued);
    const outside = folded ? not(member(true)) : hasNoList(column) ? and(values.map((v) => field(column, { not: v }))) : field(column, { notIn: values });
    return t.blank ? and([outside, blank(column, true, twoValued)]) : or([isNull(column), outside]);
  }

  function leafNode(column: PlanColumn, t: Test, twoValued: boolean): PrismaNode {
    switch (t.k) {
      case "eq":
      case "exact":
        return fieldLeaf(column, { equals: value(column, t.value) }, twoValued);
      case "ne":
        return or([isNull(column), field(column, { not: value(column, t.value) })]);
      case "blank":
        return blank(column, t.negate, twoValued);
      case "text": {
        const filter = textFilter(column, t.mode, t.text, t.caseSensitive);
        return t.negate ? or([isNull(column), { NOT: field(column, filter) }]) : fieldLeaf(column, filter, twoValued);
      }
      case "cmp":
        return fieldLeaf(column, guarded(column, own({}, t.op, bound(column, t.op, t.value))), twoValued);
      case "range": {
        const filter: Record<string, unknown> = {};
        const hi = t.hiExclusive ? "lt" : "lte";
        if (t.lo) filter["gte"] = bound(column, "gte", t.lo);
        if (t.hi) filter[hi] = bound(column, hi, t.hi);
        return fieldLeaf(column, guarded(column, filter), twoValued);
      }
      case "in":
        return inList(column, t, twoValued);
      case "ids":
        // SQLite would need `lower(col)` to keep an excluded uuid in any case excluded.
        if (t.negate && !pg && column.native === "uuid") throw unsupported(column);
        // `notIn`, never `NOT: { in }`: Prisma splits a plain `in` into chunks and merges wrong rows under NOT.
        return field(column, own({}, t.negate ? "notIn" : "in", t.values.map((operand) => value(column, operand))));
      case "key":
        // No `mode`: the comparison follows ORDER BY, which uses the column collation.
        if (t.op === "null" || !t.value) return isNull(column);
        // A Prisma Boolean filter has no `gt` or `lt`: past `false` ascending is `true`, past `true` is nothing.
        if (column.kind === "checkbox" && t.op !== "eq") return t.value.v === (t.op === "lt") ? fieldLeaf(column, { equals: !t.value.v }, twoValued) : false;
        return fieldLeaf(column, own({}, t.op === "eq" ? "equals" : t.op, value(column, t.value)), twoValued);
      case "custom":
        throw unsupported(column);
    }
  }

  function node(p: Predicate, twoValued = false): PrismaNode {
    switch (p.t) {
      case "true":
        return true;
      case "false":
        return false;
      case "leaf":
        return leafNode(p.column, p.test, twoValued);
      case "not":
        return not(node(p.item, true));
      default:
        return (p.t === "and" ? and : or)(p.items.map((item) => node(item, twoValued)));
    }
  }

  const orderBy = (terms: readonly OrderTerm[]): PrismaOrderBy =>
    terms.map(({ column, direction }) => field(column, isNullable(column) ? { sort: direction, nulls: "last" } : direction));

  return { node, orderBy, blank, textFilter };
}

